public final class OrgThreadResource: Sendable {
    private let http: HttpClient

    public init(http: HttpClient) {
        self.http = http
    }

    /// List organization-visibility threads
    ///
    /// Returns org-visibility threads for the specified organization. Every member
    /// of the organization can list these threads; they require no team membership.
    /// App-scoped developer tokens for the organization's app can list them too.
    ///
    /// - Parameters:
    ///   - org: Organization ID (`org_...`) whose org-visibility threads should be listed.
    ///   - key: Optional exact thread key, for example `archdev-room`.
    /// - Returns: Successful response
    public func list(org: String, key: String? = nil) async throws -> OrgThreadListResponse {
        var query: [(String, String)] = []
        if let key = key {
            query.append(("key", key))
        }
        return try await http.request("/api/v1/orgs/\(org)/threads", query: query)
    }

    /// Create an organization-visibility thread
    ///
    /// Creates a thread owned by the organization rather than a team, user, or agent.
    /// Every member of the organization can read and post without joining. The
    /// authenticated caller must be an organization administrator, or use an
    /// app-scoped developer token for the organization's app.
    /// When `thread.key` is supplied, creation is idempotent: a second call with the
    /// same key returns the existing org-visibility thread instead of inserting a
    /// duplicate.
    ///
    /// - Parameters:
    ///   - org: Organization ID (`org_...`) whose org-visibility threads should be listed.
    ///   - input: Request body.
    /// - Returns: The organization-visibility thread.
    public func create(org: String, input: OrgThreadCreateInput) async throws -> Thread {
        return try await http.request("/api/v1/orgs/\(org)/threads", method: "POST", body: input)
    }
}

public final class OrgResource: Sendable {
    private let http: HttpClient
    public let threads: OrgThreadResource

    public init(http: HttpClient) {
        self.http = http
        self.threads = OrgThreadResource(http: http)
    }

    /// Search organizations
    ///
    /// Returns a paginated list of organizations within the authenticated app scope,
    /// optionally filtered by a free-text search term matched against name, slug, and
    /// domain (case-insensitive). Results are ordered by relevance when a search term
    /// is provided, and by creation time descending otherwise.
    /// The response includes only public-facing organization fields: ID, name, domain,
    /// and logo. Use the developer-scoped org endpoints to access full organization
    /// records.
    /// Pagination is offset-based. Pass `page` and `page_size` to navigate through
    /// results. The `has_next` and `has_prev` fields indicate whether adjacent pages
    /// exist.
    ///
    /// - Parameters:
    ///   - search: Free-text search term matched against organization name, slug, and domain (case-insensitive). Omit to return all organizations in the app.
    ///   - page: Page number to retrieve, starting at `1`. Defaults to `1` when omitted.
    ///   - pageSize: Number of organizations to return per page. Defaults to `25`; maximum is `100`.
    /// - Returns: Successful response
    public func list(search: String? = nil, page: Int? = nil, pageSize: Int? = nil) async throws -> OrgListResponse {
        var query: [(String, String)] = []
        if let search = search {
            query.append(("search", search))
        }
        if let page = page {
            query.append(("page", String(page)))
        }
        if let pageSize = pageSize {
            query.append(("page_size", String(pageSize)))
        }
        return try await http.request("/api/v1/orgs", query: query)
    }

    /// List completed organization artifacts
    ///
    /// Returns completed system-owned organization snapshots, newest first. Private user, team, agent and thread artifacts are excluded.
    ///
    /// - Parameters:
    ///   - org: Organization ID.
    ///   - limit: Maximum snapshots returned, from 1 to 100.
    ///   - afterCursor: Opaque cursor for the next page of older snapshots.
    ///   - groupKey: Exact, case-sensitive grouping key.
    ///   - groupKeyPrefix: Nonempty literal group prefix; mutually exclusive with group_key.
    /// - Returns: Successful response
    public func artifacts(org: String, limit: Int? = nil, afterCursor: String? = nil, groupKey: String? = nil, groupKeyPrefix: String? = nil) async throws -> OrgArtifactsResponse {
        var query: [(String, String)] = []
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        if let groupKey = groupKey {
            query.append(("group_key", groupKey))
        }
        if let groupKeyPrefix = groupKeyPrefix {
            query.append(("group_key_prefix", groupKeyPrefix))
        }
        return try await http.request("/api/v1/orgs/\(org)/artifacts", query: query)
    }

    /// List an organization's linked accounts
    ///
    /// Returns the GitHub login each user in the organization signed in with, so
    /// clients can tell that a pull request's author and a Platform user are the
    /// same person. Users who never signed in with GitHub are absent. Any viewer
    /// acting within the organization can list them; other viewers get 404.
    /// Pass `user` to look up specific users instead of listing the whole
    /// organization. Results are ordered by user and paginated forward with
    /// `after_cursor`.
    ///
    /// - Parameters:
    ///   - org: Organization ID (`org_...`) whose linked accounts should be listed.
    ///   - user: Up to 100 user IDs (`usr_...`) to look up. Omit to list every user in the organization. Users in the list who are outside the organization or have no linked account are absent.
    ///   - limit: Maximum accounts returned, from 1 to 100.
    ///   - afterCursor: Opaque cursor for the next page.
    /// - Returns: Successful response
    public func linkedAccounts(org: String, user: [String]? = nil, limit: Int? = nil, afterCursor: String? = nil) async throws -> OrgLinkedAccountsResponse {
        var query: [(String, String)] = []
        if let user = user {
            for item in user {
                query.append(("user", item))
            }
        }
        if let limit = limit {
            query.append(("limit", String(limit)))
        }
        if let afterCursor = afterCursor {
            query.append(("after_cursor", afterCursor))
        }
        return try await http.request("/api/v1/orgs/\(org)/linked_accounts", query: query)
    }
}
